  assert.equal(decodeSnapshot(JSON.stringify(snapshot(2))), null);
  assert.equal(decodeSnapshot(JSON.stringify(snapshot(1, { name: 'Café' }))), null);
  for (const version of [0, 3, -1, 1.5, '1', '2', null])
    assert.equal(
